$ErrorActionPreference = 'Stop'
$restoreWorkshop = (Get-Location).Path
$restoreSnapshot = Join-Path $restoreWorkshop '08_ARHIVA\ROM-001-G01\r01-after-audit'
$expectedIndexHash = '08d454312b19fc83debe2a159b5277a274ac0e796af63d2d1d1f39900a3871ce'
function Assert-Plain([string]$path) {
 $full = [IO.Path]::GetFullPath($path)
 if ($full -ne $restoreWorkshop -and -not $full.StartsWith($restoreWorkshop + '\',[StringComparison]::OrdinalIgnoreCase)) { throw "Path outside workshop: $path" }
 $item = Get-Item -LiteralPath $full -Force
 $cursor = $item
 while ($cursor) {
  if ($cursor.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw "Reparse refused: $path" }
  $cursor = if ($cursor.PSIsContainer) { $cursor.Parent } else { $cursor.Directory }
 }
 return $item
}
function Safe-Child([string]$base,[string]$relative) {
 if ([string]::IsNullOrWhiteSpace($relative) -or [IO.Path]::IsPathRooted($relative) -or $relative -match '(^|/)\.\.?(/|$)|\\|:|//|^/|/$|[\x00-\x1f<>"|?*]') { throw "Unsafe relative path: $relative" }
 foreach ($part in $relative.Split('/')) {
  if ($part -ne $part.Trim() -or $part.EndsWith('.') -or $part -match '^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\.|$)') { throw "Unsafe Windows segment: $relative" }
 }
 $full = [IO.Path]::GetFullPath((Join-Path $base $relative))
 if (-not $full.StartsWith($base + '\',[StringComparison]::OrdinalIgnoreCase)) { throw "Path escaped base: $relative" }
 return $full
}
function Read-Tree([string]$base) {
 $null = Assert-Plain $base
 $queue = [Collections.Generic.Queue[string]]::new()
 $queue.Enqueue($base)
 $rows = [Collections.Generic.List[object]]::new()
 while ($queue.Count) {
  foreach ($item in Get-ChildItem -LiteralPath $queue.Dequeue() -Force) {
   $null = Assert-Plain $item.FullName
   if (-not $item.FullName.StartsWith($base + '\',[StringComparison]::OrdinalIgnoreCase)) { throw 'Tree path escaped base' }
   $relative = $item.FullName.Substring($base.Length + 1).Replace('\','/')
   $null = Safe-Child $base $relative
   $rows.Add([PSCustomObject]@{path=$relative;is_directory=[bool]$item.PSIsContainer;full_path=$item.FullName})
   if ($item.PSIsContainer) { $queue.Enqueue($item.FullName) }
  }
 }
 return $rows.ToArray()
}
function Verify-Entries([string]$base,$entries,[int]$strip) {
 $seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
 foreach ($entry in $entries) {
  $relative = $entry.path.Substring($strip)
  if (-not $seen.Add($relative)) { throw "Duplicate/alias entry: $relative" }
  if ($entry.sha256 -cnotmatch '^[0-9a-f]{64}$' -or $entry.size_bytes -is [bool] -or $entry.size_bytes -isnot [ValueType] -or $entry.size_bytes -lt 0 -or $entry.size_bytes -ne [long]$entry.size_bytes) { throw "Invalid index hash or size: $relative" }
  $full = Safe-Child $base $relative
  $item = Assert-Plain $full
  if ($item.PSIsContainer) { throw "Indexed path is directory: $relative" }
  $actual = (Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash.ToLowerInvariant()
  if ($actual -cne $entry.sha256 -or $item.Length -ne $entry.size_bytes) { throw "Indexed bytes mismatch: $relative" }
  [PSCustomObject]@{path=$relative;sha256=$actual;size_bytes=[long]$item.Length}
 }
}
function File-Proof([string]$relative) {
 $full = Safe-Child $restoreWorkshop $relative
 $item = Assert-Plain $full
 [PSCustomObject]@{path=$relative;sha256=(Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash.ToLowerInvariant();size_bytes=[long]$item.Length}
}

$started = [DateTime]::UtcNow.ToString('o')
$indexPath = Join-Path $restoreSnapshot 'index.json'
$null = Assert-Plain $indexPath
$indexHash = (Get-FileHash -LiteralPath $indexPath -Algorithm SHA256).Hash.ToLowerInvariant()
if ($indexHash -cne $expectedIndexHash) { throw 'Index differs from pinned digest' }
$sidecar = File-Proof '08_ARHIVA/ROM-001-G01/r01-after-audit/index.sha256'
if ((Get-Content -LiteralPath (Join-Path $restoreSnapshot 'index.sha256') -Raw -Encoding UTF8).Trim() -cne $expectedIndexHash) { throw 'Sidecar mismatch' }
$index = Get-Content -LiteralPath $indexPath -Raw -Encoding UTF8 | ConvertFrom-Json
if ($index.entries.Count -ne 751 -or $index.deliverable_id -cne 'ROM-001-G01' -or $index.round_id -cne 'r01-after-audit' -or $index.schema_version -ne 2 -or $index.editorial_approval_issued -ne $false) { throw 'Index metadata mismatch' }
$verified = @(Verify-Entries $restoreSnapshot $index.entries 0)
$tree = @(Read-Tree $restoreSnapshot)
$treeFiles = @($tree | Where-Object { -not $_.is_directory } | ForEach-Object path)
$expectedFiles = @($index.entries.path) + @('index.json','index.sha256')
if (@(Compare-Object $expectedFiles $treeFiles).Count) { throw 'Snapshot has missing or extra files' }
$proofs = @(
 File-Proof '08_ARHIVA/ROM-001-G01/r01-after-audit/index.json'
 $sidecar
 File-Proof '06_REGISTRU/PROBE_ARHIVA/ROM-001-G01-r01-after/index.json'
 File-Proof '06_REGISTRU/PROBE_ARHIVA/ROM-001-G01-r01-after/index.sha256'
 File-Proof '06_REGISTRU/PROBE_ARHIVA/ROM-001-G01-r01-after/provenienta.json'
 File-Proof '06_REGISTRU/REZULTATE/ROM-001-G01-AFTER-ARCHIVE-receipt-r01.json'
)
if ($proofs[2].sha256 -cne $indexHash -or $proofs[3].sha256 -cne $sidecar.sha256 -or $proofs[2].size_bytes -ne $proofs[0].size_bytes -or $proofs[3].size_bytes -ne $sidecar.size_bytes) { throw 'Flat copies differ' }
$receipt = Get-Content -LiteralPath (Safe-Child $restoreWorkshop $proofs[5].path) -Raw -Encoding UTF8 | ConvertFrom-Json
if ($receipt.archived -ne $true -or $receipt.deliverable_id -cne $index.deliverable_id -or $receipt.round_id -cne $index.round_id -or $receipt.index_sha256 -cne $indexHash -or $receipt.files_archived -ne $verified.Count -or $receipt.editorial_approval_issued -ne $false -or [IO.Path]::GetFullPath($receipt.snapshot_path) -ne $restoreSnapshot) { throw 'Receipt mismatch' }
$provenance = Get-Content -LiteralPath (Safe-Child $restoreWorkshop $proofs[4].path) -Raw -Encoding UTF8 | ConvertFrom-Json
if ($provenance.index_sha256 -cne $indexHash -or $provenance.entries_checked -ne $verified.Count -or $provenance.all_entries_match -ne $true -or $provenance.mismatches.Count -ne 0 -or $provenance.receipt_match -ne $true -or $provenance.sidecar_match -ne $true) { throw 'Flat provenance mismatch' }
$contract = @($verified | Where-Object path -eq 'sources/06_REGISTRU/CONTRACTE/ROM-001-G01-r01.json')
if ($contract.Count -ne 1 -or $contract[0].sha256 -cne '07110637be555cb455727593ebdf9ef88de1f27c12b5a389f53e79544bd6cebe') { throw 'Pinned contract mismatch' }
[PSCustomObject]@{
 started_at=$started;finished_at=[DateTime]::UtcNow.ToString('o');index_sha256=$indexHash;indexed_entries=$verified.Count;
 indexed_bytes=[long](($verified | Measure-Object size_bytes -Sum).Sum);source_entries=@($index.entries | Where-Object path -like 'sources/*').Count;
 actual_snapshot_files=$treeFiles.Count;snapshot_subdirectories=@($tree | Where-Object is_directory).Count;all_entries_match=$true;exact_file_set=$true;all_paths_confined=$true;no_reparse=$true;
 sidecar_match=$true;flat_copies_byte_identical=$true;receipt_match=$true;provenance_consistent=$true;proofs=$proofs;receipt=$receipt;provenance=$provenance;contract=$contract[0];mismatches=@()
} | ConvertTo-Json -Depth 15 -Compress

